                this.stateService.historyPending = false;
                this.response.history = res;
                this.response.historyError = '';
                this.callCustom('resolveFetchHistory', res);
                resolve();
            }, (err) => {
                this.stateService.historyPending = false;
                this.response.historyError = err;
                this.callCustom('rejectFetchHistory', err);
                reject();
